//! Throwaway probe (P3 measurement, never committed): does a harness shot on the stand paint
//! what an app paints from Rust through a widget on an `<object data>`?

use anyrender::{AntiAliasing, PaintScene as _};
use blitz_dom::Widget;
use blitz_dom::node::ComputedStyles;
use dioxus::prelude::*;
use dioxus_native_dom::CustomWidgetAttr;
use peniko::kurbo::{Affine, Rect};
use peniko::{Color, Fill};
use seven_guis::stand;

struct Red;

impl Widget for Red {
    fn paint(
        &mut self,
        _ctx: &mut dyn anyrender::RenderContext,
        _styles: &ComputedStyles,
        width: u32,
        height: u32,
        _scale: f64,
    ) -> anyrender::Scene {
        let mut scene = anyrender::Scene::new();
        scene.fill(
            Fill::NonZero,
            Affine::IDENTITY,
            Color::from_rgb8(255, 0, 0),
            None,
            &Rect::new(0.0, 0.0, f64::from(width), f64::from(height)),
            AntiAliasing::default(),
        );
        scene
    }
}

#[component]
fn Probe() -> Element {
    let attr = use_hook(|| CustomWidgetAttr::new(Red));
    rsx! {
        object { id: "probe-canvas", style: "display: block; width: 200px; height: 100px;", "data": attr }
    }
}

fn pixel(raster: &blitz_test_harness::Raster, x: u32, y: u32) -> [u8; 4] {
    let i = ((y * raster.width + x) * 4) as usize;
    [
        raster.rgba[i],
        raster.rgba[i + 1],
        raster.rgba[i + 2],
        raster.rgba[i + 3],
    ]
}

#[test]
fn widget_paints_in_a_harness_shot() {
    for incremental in [false, true] {
        let mut harness = stand::boot_alone(Probe, || (), stand::options(incremental));
        harness.settle();
        let shot = harness.screenshot().expect("shot");
        let probe = pixel(&shot, 50, 50);
        let outside = pixel(&shot, 400, 400);
        println!(
            "PROBE incremental={incremental} inside(50,50)={:?} outside(400,400)={:?}",
            probe, outside
        );
        assert_eq!(probe, [255, 0, 0, 255], "the widget's red is in the shot");
    }
}

//! Throwaway probe (P4 measurement, never committed): through an in-process driver session on a
//! component booted by `stand::boot_alone`, is an `<object data>` widget in the snapshot, and what
//! does its element shot read?

use anyrender::{AntiAliasing, PaintScene as _};
use blitz_dom::Widget;
use blitz_dom::node::ComputedStyles;
use dioxus::prelude::*;
use dioxus_native_dom::CustomWidgetAttr;
use escher_driver::{ArgValue, Call, Outcome, Session};
use peniko::kurbo::{Affine, Rect};
use peniko::{Color, Fill};
use seven_guis::stand;

struct Red;

impl Widget for Red {
    fn paint(
        &mut self,
        _ctx: &mut dyn anyrender::RenderContext,
        _styles: &ComputedStyles,
        width: u32,
        height: u32,
        _scale: f64,
    ) -> anyrender::Scene {
        let mut scene = anyrender::Scene::new();
        scene.fill(
            Fill::NonZero,
            Affine::IDENTITY,
            Color::from_rgb8(255, 0, 0),
            None,
            &Rect::new(0.0, 0.0, f64::from(width), f64::from(height)),
            AntiAliasing::default(),
        );
        scene
    }
}

#[component]
fn Probe() -> Element {
    let attr = use_hook(|| CustomWidgetAttr::new(Red));
    rsx! {
        object { id: "probe-canvas", style: "display: block; width: 200px; height: 100px;", "data": attr }
    }
}

fn call(verb: &str, args: &[(&str, ArgValue)]) -> Call {
    Call {
        verb: verb.to_string(),
        args: args
            .iter()
            .map(|(n, v)| (n.to_string(), v.clone()))
            .collect(),
    }
}

#[test]
fn probe2() {
    for incremental in [false, true] {
        let mut session = Session::start("canvas", || {
            stand::boot_alone(Probe, || (), stand::options(incremental))
        })
        .expect("label");
        let snap = session.harness().doc.snapshot();
        let node = snap.get("probe-canvas");
        println!(
            "PROBE2 incremental={incremental} in_snapshot={} bounds={:?} role={:?}",
            node.is_some(),
            node.map(|n| (n.bounds.x, n.bounds.y, n.bounds.width, n.bounds.height)),
            node.map(|n| format!("{:?}", n.role)),
        );
        let raster = session.harness_mut().screenshot().expect("raster");
        let whole = session.run(&call("screenshot", &[]));
        if let Ok(Outcome::Shot { width, height, png }) = whole {
            let decoder = png::Decoder::new(std::io::Cursor::new(png));
            let mut reader = decoder.read_info().expect("png");
            let mut buf = vec![0; reader.output_buffer_size().expect("size")];
            let info = reader.next_frame(&mut buf).expect("frame");
            buf.truncate(info.buffer_size());
            println!(
                "PROBE2 whole {width}x{height} equal_to_raster={}",
                buf == raster.rgba
            );
        } else {
            println!("PROBE2 whole refused or other");
        }
        let el = session.run(&call(
            "screenshot",
            &[("id", ArgValue::Text("probe-canvas".to_string()))],
        ));
        match el {
            Ok(Outcome::Shot { width, height, png }) => {
                let decoder = png::Decoder::new(std::io::Cursor::new(png));
                let mut reader = decoder.read_info().expect("png");
                let mut buf = vec![0; reader.output_buffer_size().expect("size")];
                let info = reader.next_frame(&mut buf).expect("frame");
                buf.truncate(info.buffer_size());
                let mut distinct: Vec<[u8; 4]> = Vec::new();
                for px in buf.chunks(4) {
                    let p = [px[0], px[1], px[2], px[3]];
                    if !distinct.contains(&p) {
                        distinct.push(p);
                    }
                }
                println!("PROBE2 element {width}x{height} distinct={distinct:?}");
            }
            Ok(_) => println!("PROBE2 element other outcome"),
            Err(r) => println!("PROBE2 element refused {}", r),
        }
    }
}
